data = cells('Allowed assignments', 'L812:N820')
tasks = list(set((r[0] for r in data)))
workers = list(set((r[1] for r in data)))
avail_workers = [w for w in workers if w != 'Dune']
costs = {(r[0], r[1]): r[2] for r in data}
min_cost = float('inf')
for p in itertools.permutations(avail_workers, len(tasks)):
    assignment = list(zip(tasks, p))
    possible = True
    total = 0
    for t, w in assignment:
        if (t, w) in costs:
            total += costs[t, w]
        else:
            possible = False
            break
    if possible and total < min_cost:
        min_cost = total
result = min_cost

