    f = label(sheet, f'H{r}')
    t = label(sheet, f'I{r}')
    p = num(sheet, f'G{r}')
    prob[(f, t)] = p

states = ['Idle', 'Active', 'Done']
v = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}
for step in range(4):
